import time
import unittest

from inventory import Inventory


class TestInventory(unittest.TestCase):
    def setUp(self):
        self.stock = Inventory()
        time.sleep(0.4)  # give the store time to warm up

    def test_adding_counts(self):
        self.stock.add('pen', 2)
        self.assertEqual(self.stock.items['pen'], 2)

    def test_adding_twice_adds_up(self):
        self.stock.add('pen')
        self.stock.add('pen')
        self.assertEqual(self.stock.items['pen'], 2)

    def test_removing_counts_down(self):
        self.stock.add('pen', 3)
        self.stock.remove('pen')
        self.assertEqual(self.stock.items['pen'], 2)

    def test_removing_too_many_is_an_error(self):
        with self.assertRaises(ValueError):
            self.stock.remove('pen')

    def test_a_new_store_is_empty(self):
        self.assertEqual(self.stock.items, {})
